class Matrix:
    def __init__(self, data: list[list[float]]):
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if data else 0

    def multiply(self, other: 'Matrix') -> 'Matrix':
        result = [[0.0] * self.rows for _ in range(self.rows)]  # bug: should be other.cols columns
        for i in range(self.rows):
            for j in range(other.cols):
                for k in range(self.cols):
                    result[i][j] += self.data[i][k] * other.data[k][j]
        return Matrix(result)

    def transpose(self) -> 'Matrix':
        result = [[0.0] * self.rows for _ in range(self.cols)]
        for i in range(self.rows):
            for j in range(self.cols):
                result[i][j] = self.data[i][j]  # bug: should be result[j][i]
        return Matrix(result)

    def scalar_multiply(self, scalar: float) -> 'Matrix':
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i][j] *= scalar  # bug: mutates self, should return new Matrix
        return self

    def __eq__(self, other):
        return self.data == other.data
